@page "/enroll"

<PageTitle>Enrollment Request</PageTitle>

<h1>Enrollment Request</h1>
<p class="text-muted">Submit your enrollment request below. You will receive confirmation via your university email.</p>

@if (Submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Thank you, <strong>@Model.StudentName</strong>. Your enrollment request for <strong>@SelectedCourseTitle</strong> has been received.</p>
        <hr />
        <p class="mb-0"><a href="/courses">Browse more courses</a> or <a href="/enroll">submit another request</a>.</p>
    </div>
}
else
{
    <form method="post" @formname="enrollment" @onsubmit="HandleSubmit">
        <AntiforgeryToken />

        <div class="row">
            <div class="col-md-8">
                <div class="mb-3">
                    <label for="studentName" class="form-label">Full Name</label>
                    <input type="text" id="studentName" name="Model.StudentName" value="@Model.StudentName" class="form-control" required />
                    @if (Errors.ContainsKey(nameof(Model.StudentName)))
                    {
                        <div class="text-danger mt-1">@Errors[nameof(Model.StudentName)]</div>
                    }
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID</label>
                    <input type="text" id="studentId" name="Model.StudentId" value="@Model.StudentId" class="form-control" placeholder="e.g., STU12345" required />
                    @if (Errors.ContainsKey(nameof(Model.StudentId)))
                    {
                        <div class="text-danger mt-1">@Errors[nameof(Model.StudentId)]</div>
                    }
                </div>

                <div class="mb-3">
                    <label for="courseId" class="form-label">Course</label>
                    <select id="courseId" name="Model.CourseId" class="form-select" required>
                        <option value="0">-- Select a course --</option>
                        @foreach (var course in AllCourses)
                        {
                            <option value="@course.Id" selected="@(Model.CourseId == course.Id)">@course.CourseCode — @course.Title</option>
                        }
                    </select>
                    @if (Errors.ContainsKey(nameof(Model.CourseId)))
                    {
                        <div class="text-danger mt-1">@Errors[nameof(Model.CourseId)]</div>
                    }
                </div>

                <button type="submit" class="btn btn-success">Submit Enrollment Request</button>
                <a href="/courses" class="btn btn-outline-secondary ms-2">Cancel</a>
            </div>
        </div>
    </form>
}

@code {
    [Inject] private UniversityCourseCatalog.Services.CatalogService CatalogService { get; set; } = default!;

    [SupplyParameterFromQuery] public int? CourseId { get; set; }
    [SupplyParameterFromForm] public UniversityCourseCatalog.Models.EnrollmentRequest Model { get; set; } = new();

    private List<UniversityCourseCatalog.Models.Course> AllCourses { get; set; } = new();
    private Dictionary<string, string> Errors { get; set; } = new();
    private bool Submitted { get; set; }
    private string SelectedCourseTitle { get; set; } = string.Empty;

    protected override void OnInitialized()
    {
        AllCourses = CatalogService.GetAllCourses();
        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        Errors.Clear();
        var validationResults = new List<System.ComponentModel.DataAnnotations.ValidationResult>();
        var context = new System.ComponentModel.DataAnnotations.ValidationContext(Model);
        if (!System.ComponentModel.DataAnnotations.Validator.TryValidateObject(Model, context, validationResults, true))
        {
            foreach (var result in validationResults)
            {
                foreach (var member in result.MemberNames)
                {
                    if (!Errors.ContainsKey(member))
                        Errors[member] = result.ErrorMessage ?? "Invalid value.";
                }
            }
            return;
        }

        SelectedCourseTitle = AllCourses.FirstOrDefault(c => c.Id == Model.CourseId)?.Title ?? "Unknown Course";
        Submitted = true;
    }
}

